class Solution {
    public int[] splitAround(int[] values, int pivot) {
        Integer[] a = Arrays.stream(values).boxed().toArray(Integer[]::new);
        Arrays.sort(a, Comparator.comparingInt(x -> x < pivot ? 0 : (x == pivot ? 1 : 2)));
        return Arrays.stream(a).mapToInt(Integer::intValue).toArray();
    }
}

