class Solution {
public:
    vector<int> splitAround(vector<int>& values, int pivot) {
        auto group = [pivot](int x) { return x < pivot ? 0 : (x == pivot ? 1 : 2); };
        vector<int> a = values;
        stable_sort(a.begin(), a.end(), [&](int x, int y) { return group(x) < group(y); });
        return a;
    }
};

