typedef struct { int value, group, at; } Item;

static int by_group(const void* p, const void* q) {
    const Item *a = p, *b = q;
    return a->group != b->group ? a->group - b->group : a->at - b->at;
}

int* splitAround(int* values, int valuesSize, int pivot, int* returnSize) {
    Item* items = malloc(valuesSize * sizeof(Item));
    for (int i = 0; i < valuesSize; i++)
        items[i] = (Item){values[i], values[i] < pivot ? 0 : (values[i] == pivot ? 1 : 2), i};
    qsort(items, valuesSize, sizeof(Item), by_group);
    int* out = malloc(valuesSize * sizeof(int));
    for (int i = 0; i < valuesSize; i++) out[i] = items[i].value;
    free(items);
    *returnSize = valuesSize;
    return out;
}

