class Solution {
    public int[] splitAround(int[] values, int pivot) {
        int less = 0, equal = 0;
        for (int x : values) { if (x < pivot) less++; else if (x == pivot) equal++; }
        int[] out = new int[values.length];
        int a = 0, b = less, c = less + equal;
        for (int x : values) {
            if (x < pivot) out[a++] = x;
            else if (x == pivot) out[b++] = x;
            else out[c++] = x;
        }
        return out;
    }
}

